    53→      @JsonProperty("filter") final DimFilter filter,
    54→      @JsonProperty("transforms") final List<Transform> transforms
    55→  )
    56→  {
    57→    this.filter = filter;
    58→    this.transforms = transforms == null ? ImmutableList.of() : transforms;
    59→
    60→    // Check for name collisions.
    61→    final Set<String> seen = new HashSet<>();
    62→    for (Transform transform : this.transforms) {
    63→      if (!seen.add(transform.getName())) {
    64→        throw new ISE("Transform name '%s' cannot be used twice", transform.getName());
    65→      }
    66→    }
    67→  }
