    77→  public <T> T configurate(
    78→      Properties props,
    79→      String propertyPrefix,
    80→      Class<T> clazz,
    81→      @Nullable Class<? extends T> defaultClass
    82→  ) throws ProvisionException
    83→  {
    84→    verifyClazzIsConfigurable(jsonMapper, clazz, defaultClass);
    85→
    86→    // Make it end with a period so we only include properties with sub-object thingies.
    87→    final String propertyBase = propertyPrefix.endsWith(".") ? propertyPrefix : propertyPrefix + ".";
    88→
    89→    Map<String, Object> jsonMap = new HashMap<>();
    90→    for (String prop : props.stringPropertyNames()) {
    91→      if (prop.startsWith(propertyBase)) {
    92→        final String propValue = props.getProperty(prop);
    93→        Object value;
    94→        try {
    95→          // If it's a String Jackson wants it to be quoted, so check if it's not an object or array and quote.
    96→          String modifiedPropValue = propValue;
    97→          if (!(modifiedPropValue.startsWith("[") || modifiedPropValue.startsWith("{"))) {
    98→            modifiedPropValue = jsonMapper.writeValueAsString(propValue);
    99→          }
   100→          value = jsonMapper.readValue(modifiedPropValue, Object.class);
   101→        }
