   139→      List<String> messages = new ArrayList<>();
   140→
   141→      for (ConstraintViolation<T> violation : violations) {
   142→        StringBuilder path = new StringBuilder();
   143→        try {
   144→          Class<?> beanClazz = violation.getRootBeanClass();
   145→          final Iterator<Path.Node> iter = violation.getPropertyPath().iterator();
   146→          while (iter.hasNext()) {
   147→            Path.Node next = iter.next();
   148→            if (next.getKind() == ElementKind.PROPERTY) {
