   157→              JsonProperty annotation = theField.getAnnotation(JsonProperty.class);
   158→              final boolean noAnnotationValue = annotation == null || Strings.isNullOrEmpty(annotation.value());
   159→              final String pathPart = noAnnotationValue ? fieldName : annotation.value();
   160→              if (path.length() == 0) {
   161→                path.append(pathPart);
   162→              } else {
   163→                path.append(".").append(pathPart);
   164→              }
   165→            }
   166→          }
   167→        }
   168→        catch (NoSuchFieldException e) {
