   216→    }
   217→    String nestedKey = property.substring(0, dotIndex);
   218→    Object nested = targetMap.computeIfAbsent(nestedKey, k -> new HashMap<String, Object>());
   219→    if (!(nested instanceof Map)) {
   220→      // Clash is possible between properties, which are used to configure different objects: e. g.
   221→      // druid.emitter=parametrized is used to configure Emitter class, and druid.emitter.parametrized.xxx=yyy is used
   222→      // to configure ParametrizedUriEmitterConfig object. So skipping xxx=yyy key-value pair when configuring Emitter
   223→      // doesn't make any difference. That is why we just log this situation, instead of throwing an exception.
   224→      log.info(
   225→          "Skipping %s property: one of it's prefixes is also used as a property key. Prefix: %s",
   226→          originalProperty,
   227→          propertyPrefix
   228→      );
   229→      return;
   230→    }
   231→    Map<String, Object> nestedMap = (Map<String, Object>) nested;
   232→    hieraricalPutValue(propertyPrefix, originalProperty, property.substring(dotIndex + 1), value, nestedMap);
   233→  }
