   235→  @VisibleForTesting
   236→  public static <T> void verifyClazzIsConfigurable(
   237→      ObjectMapper mapper,
   238→      Class<T> clazz,
   239→      @Nullable Class<? extends T> defaultClass
   240→  )
   241→  {
   242→    if (defaultClass != null) {
   243→      try {
   244→        defaultClass.getConstructor();
   245→      }
   246→      catch (NoSuchMethodException e) {
   247→        throw new ProvisionException(
   248→            StringUtils.format(
   249→                "JsonConfigurator requires default classes to have zero-arg constructors. %s doesn't",
   250→                defaultClass
   251→            )
   252→        );
   253→      }
   254→    }
   255→
   256→    final List<BeanPropertyDefinition> beanDefs = mapper.getSerializationConfig()
   257→                                                        .introspect(mapper.constructType(clazz))
   258→                                                        .findProperties();
   259→    for (BeanPropertyDefinition beanDef : beanDefs) {
   260→      final AnnotatedField field = beanDef.getField();
   261→      if (field == null || !field.hasAnnotation(JsonProperty.class)) {
   262→        throw new ProvisionException(
   263→            StringUtils.format(
   264→                "JsonConfigurator requires Jackson-annotated Config objects to have field annotations. %s doesn't",
   265→                clazz
   266→            )
   267→        );
   268→      }
   269→    }
   270→  }
